// Liefert Gespraechs-Historie einer Session (paginiert, neueste zuerst geholt,
// chronologisch zurueckgegeben). Polling-frei: wird nur beim Laden/Blaettern gerufen.
const q = $('History Webhook').first().json.query || {};
const sid = q.session_id || '';
const before = parseInt(q.before_id || '0', 10) || 0;
const limit = Math.min(parseInt(q.limit || '30', 10) || 30, 100);
if (!sid) return [{ json: { messages: [] } }];
let url = '{{SUPABASE_URL}}/rest/v1/conversations?session_id=eq.' + encodeURIComponent(sid)
  + '&select=id,role,content,created_at&order=id.desc&limit=' + limit;
if (before > 0) url += '&id=lt.' + before;
const rows = await helpers.httpRequest({ method: 'GET', url, headers: { 'apikey': '{{SUPABASE_SERVICE_KEY}}' } });
const list = Array.isArray(rows) ? rows.reverse() : [];
return [{ json: { messages: list, oldest_id: list.length ? list[0].id : null } }];
